from vdriftbench.config import Config
from vdriftbench.io_utils import load_sample_results_jsonl
from vdriftbench.pipeline import genre_rounds, _round_outcome

config = Config()
before = {r.sample_id: r for r in load_sample_results_jsonl('/root/vdriftbench/data/v3.15_flash_run/results.jsonl.bak_20260917_115024')}
after = {r.sample_id: r for r in load_sample_results_jsonl('/root/vdriftbench/data/v3.15_flash_run/results.jsonl')}

def r5_any(r):
    gr = genre_rounds(r.rounds)
    return gr and any(_round_outcome(x, config)=='成功' for x in gr)

def r5_first(r):
    gr = genre_rounds(r.rounds)
    return gr and _round_outcome(gr[0], config)=='成功'

changed=[]
for sid in before:
    if before[sid].rounds != after[sid].rounds:
        changed.append(sid)
print('rows with different rounds', len(changed), changed)

# metrics full cohort
for name,d in [('before',before),('after',after)]:
    rows=list(d.values()); n=len(rows)
    print(name, 'r5+retry', sum(r5_any(r) for r in rows), f"{100*sum(r5_any(r) for r in rows)/n:.2f}%")
    print(name, 'r5_first', sum(r5_first(r) for r in rows), f"{100*sum(r5_first(r) for r in rows)/n:.2f}%")

imp=[]; wor=[]
for sid in changed:
    b,a=r5_any(before[sid]), r5_any(after[sid])
    if b!=a: (imp if a else wor).append(sid)
print('among changed', len(changed), 'improved', imp, 'worsened', wor)
